-- Apply ONCE to the existing Batch Tracker database after schema 001.
CREATE TABLE s_schema_versions(version INT PRIMARY KEY,applied_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE s_settings(id INT PRIMARY KEY,currency CHAR(3) NOT NULL DEFAULT 'PKR',checkout_enabled BOOLEAN NOT NULL DEFAULT FALSE,cod_enabled BOOLEAN NOT NULL DEFAULT FALSE,support_email VARCHAR(254),support_phone VARCHAR(30),company_address VARCHAR(500),version INT NOT NULL DEFAULT 1);
INSERT INTO s_settings(id) VALUES(1);
CREATE TABLE s_categories(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,is_active BOOLEAN NOT NULL DEFAULT TRUE,version INT NOT NULL DEFAULT 1);
INSERT INTO s_categories(name,slug) VALUES('Dried fruit','dried-fruit'),('Nuts','nuts'),('Oils','oils'),('Teas & herbs','teas-herbs'),('Grains','grains'),('Handicrafts','handicrafts');
CREATE TABLE s_media(id BIGINT PRIMARY KEY AUTO_INCREMENT,file_name VARCHAR(80) NOT NULL UNIQUE,content_type VARCHAR(40) NOT NULL,alt_text VARCHAR(250) NOT NULL,rights_confirmed BOOLEAN NOT NULL,consent_confirmed BOOLEAN NOT NULL,is_documentary BOOLEAN NOT NULL,created_by BIGINT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE s_products(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,category_id BIGINT NOT NULL,operational_product_id BIGINT NOT NULL,summary VARCHAR(500) NOT NULL,description TEXT NOT NULL,origin VARCHAR(200) NOT NULL,ingredients TEXT NOT NULL,allergens TEXT NOT NULL,storage TEXT NOT NULL,image_ids JSON NOT NULL,published BOOLEAN NOT NULL DEFAULT FALSE,featured BOOLEAN NOT NULL DEFAULT FALSE,version INT NOT NULL DEFAULT 1,FOREIGN KEY(category_id) REFERENCES s_categories(id),FOREIGN KEY(operational_product_id) REFERENCES products(id));
CREATE TABLE s_variants(id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT NOT NULL,label VARCHAR(100) NOT NULL,sku VARCHAR(100) NOT NULL UNIQUE,price DECIMAL(15,2) NOT NULL,net_weight_kg DECIMAL(15,3) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,version INT NOT NULL DEFAULT 1,FOREIGN KEY(product_id) REFERENCES s_products(id),CHECK(price>0),CHECK(net_weight_kg>0));
CREATE TABLE s_allocations(id BIGINT PRIMARY KEY AUTO_INCREMENT,variant_id BIGINT NOT NULL,lot_id BIGINT NOT NULL,quantity INT NOT NULL,reserved INT NOT NULL DEFAULT 0,FOREIGN KEY(variant_id) REFERENCES s_variants(id),FOREIGN KEY(lot_id) REFERENCES packaging_lots(id),UNIQUE(variant_id,lot_id),CHECK(quantity>=0),CHECK(reserved>=0 AND reserved<=quantity));
CREATE TABLE s_content(id BIGINT PRIMARY KEY AUTO_INCREMENT,type ENUM('Page','Programme','Story','Event','Policy') NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,title VARCHAR(200) NOT NULL,summary VARCHAR(500) NOT NULL,body MEDIUMTEXT NOT NULL,programme_status ENUM('Planned','Active','Completed') NOT NULL DEFAULT 'Planned',event_date DATETIME(6),image_ids JSON NOT NULL,published BOOLEAN NOT NULL DEFAULT FALSE,version INT NOT NULL DEFAULT 1,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
