INSERT INTO s_content(type,slug,title,summary,body,image_ids) VALUES('Policy','shipping','Shipping and delivery','','','[]'),('Policy','returns','Returns and refunds','','','[]'),('Policy','privacy','Privacy policy','','','[]'),('Policy','terms','Terms and conditions','','','[]');
CREATE TABLE s_shipping(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,country_code CHAR(2) NOT NULL DEFAULT 'PK',charge DECIMAL(15,2) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT FALSE,version INT NOT NULL DEFAULT 1,CHECK(charge>=0));
CREATE TABLE s_orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,reference VARCHAR(50) NOT NULL UNIQUE,request_id CHAR(36) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,token_hash CHAR(64) NOT NULL,protected_token TEXT NOT NULL,policy_snapshot JSON NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(30) NOT NULL,address VARCHAR(500) NOT NULL,city VARCHAR(100) NOT NULL,postal_code VARCHAR(20) NOT NULL,country_code CHAR(2) NOT NULL,currency CHAR(3) NOT NULL,subtotal DECIMAL(15,2) NOT NULL,shipping DECIMAL(15,2) NOT NULL,discount DECIMAL(15,2) NOT NULL DEFAULT 0,total DECIMAL(15,2) NOT NULL,status ENUM('Pending','Confirmed','Shipped','Delivered','Cancelled','Expired') NOT NULL DEFAULT 'Pending',payment_status ENUM('DueOnDelivery','Collected') NOT NULL DEFAULT 'DueOnDelivery',expires_at DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),customer_id BIGINT NOT NULL,dispatch_id BIGINT NULL,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(dispatch_id) REFERENCES dispatches(id));
CREATE TABLE s_order_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,variant_id BIGINT NOT NULL,product_name VARCHAR(150) NOT NULL,variant_label VARCHAR(100) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(15,2) NOT NULL,line_total DECIMAL(15,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES s_orders(id),FOREIGN KEY(variant_id) REFERENCES s_variants(id));
CREATE TABLE s_reservations(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,allocation_id BIGINT NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES s_orders(id),FOREIGN KEY(allocation_id) REFERENCES s_allocations(id),UNIQUE(order_id,allocation_id),CHECK(quantity>0));
CREATE TABLE s_enquiries(id BIGINT PRIMARY KEY AUTO_INCREMENT,type ENUM('Contact','Wholesale') NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(254) NOT NULL,business VARCHAR(150),country VARCHAR(100),products VARCHAR(500),quantity VARCHAR(200),message TEXT NOT NULL,status ENUM('New','Handled') NOT NULL DEFAULT 'New',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE s_order_events(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,event VARCHAR(100) NOT NULL,details JSON NOT NULL,actor_id BIGINT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_id) REFERENCES s_orders(id),FOREIGN KEY(actor_id) REFERENCES users(id));
INSERT INTO s_schema_versions(version) VALUES(101);
